import React, { useState } from "react";
import "../Styles/UserProfile.css";

const UserProfile = () => {
  // User info (mock data)
  const [user, setUser] = useState({
    name: "Aisha Ahmed",
    email: "aisha@gmail.com",
    specialization: "Information Technology",
    age: 22,
    cv: null,
  });

  // Uploaded CV
  const [cvFile, setCvFile] = useState(null);

  // Job history (applied, completed)
  const [jobHistory, setJobHistory] = useState([
    {
      id: 1,
      title: "Poster Designer",
      company: "Dhofar Events",
      status: "Completed",
      payout: "8 OMR",
    },
    {
      id: 2,
      title: "Front-End Developer Intern",
      company: "UTAS Innovation Center",
      status: "In Progress",
      payout: "30 OMR",
    },
  ]);

  // Handle CV Upload
  const handleUploadCV = (e) => {
    const file = e.target.files[0];
    if (file) {
      setCvFile(file);
      setUser({ ...user, cv: file.name });
    }
  };

  return (
    <div className="profile-page">
      {/* ----- User Info ----- */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">👤</div>
          <div>
            <h2 className="profile-name">{user.name}</h2>
            <p className="profile-email">{user.email}</p>
            <p className="profile-detail">
              {user.specialization} • Age: {user.age}
            </p>
            <div className="cv-section">
              <span className="cv-label">Student CV:</span>
              <label className="upload-btn">
                <input
                  type="file"
                  accept=".pdf,.doc,.docx"
                  onChange={handleUploadCV}
                  style={{ display: "none" }}
                />
                ⬆ Upload CV
              </label>
              {cvFile && (
                <a
                  href={URL.createObjectURL(cvFile)}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="cv-link"
                >
                  📄 {cvFile.name}
                </a>
              )}
            </div>
          </div>
        </div>
        <button className="update-btn">Update your Info</button>
      </div>

      {/* ----- Recent Activity ----- */}
      <div className="activity-box">
        <h3>Recent activity</h3>
        <p>• Applied: {jobHistory.length} job(s)</p>
      </div>

      {/* ----- Job History ----- */}
      <div className="history-box">
        <h3>Job History</h3>
        {jobHistory.map((job) => (
          <div key={job.id} className="job-item">
            <div>
              <h4>{job.title}</h4>
              <p>{job.company}</p>
            </div>
            <p
              className={`status ${job.status.toLowerCase().replace(" ", "-")}`}
            >
              {job.status}
            </p>
            <span className="payout">{job.payout}</span>
          </div>
        ))}
      </div>

      {/* ----- Payment Info ----- */}
      <div className="payment-box">
        <div>
          <h3>Payment details</h3>
          <p>Bank Name: Bank Muscat</p>
          <p>Account Number: *******1234</p>
        </div>
        <button className="update-btn">Update your Payment</button>
      </div>
    </div>
  );
};

export default UserProfile;
